import React, { useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Ge.css";

function Generate() {
  const canvasRef = useRef();
  const [imagePaths, setImagePaths] = useState([]);
  const [isFading, setIsFading] = useState(false);
  const [effects, setEffects] = useState({
    grain: { intensity: 8, gamma: 1.2 },
    scanlines: { gap: 4, alpha: 0.05 },
    glitch: { lineHeight: 2, shiftAmount: 0 },
    saturation: { value: 100 }
  });
  const animationRef = useRef();
  const navigate = useNavigate();

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("selectedImages") || "[]");
    if (!stored.length) {
      navigate("/");
      return;
    }
    setImagePaths(stored);
    generateImage(stored);
    return () => cancelAnimationFrame(animationRef.current);
  }, []);

  // --- [이펙트 함수들] ---
  const generateGrain = (ctx, width, height) => {
    const { intensity } = effects.grain;
    if (intensity <= 0) return;
    const grainData = ctx.getImageData(0, 0, width, height);
    const data = grainData.data;
    for (let i = 0; i < data.length; i += 4) {
      const noise = Math.floor(Math.random() * intensity) - intensity / 2;
      data[i] = Math.min(255, Math.max(0, data[i] + noise));
      data[i + 1] = Math.min(255, Math.max(0, data[i + 1] + noise));
      data[i + 2] = Math.min(255, Math.max(0, data[i + 2] + noise));
    }
    ctx.putImageData(grainData, 0, 0);
  };

  const applyScanlines = (ctx, width, height) => {
    const { alpha } = effects.scanlines;
    if (alpha <= 0) return;
    ctx.save();
    ctx.fillStyle = `rgba(0,0,0,${alpha})`;
    for (let y = 0; y < height; y += effects.scanlines.gap) {
      ctx.fillRect(0, y, width, 1);
    }
    ctx.restore();
  };

  const applyGlitchEffect = (ctx, width, height) => {
    const { shiftAmount } = effects.glitch;
    if (shiftAmount <= 0) return;
    for (let y = 0; y < height; y += effects.glitch.lineHeight * 4) {
      const shift = (Math.random() - 0.5) * shiftAmount;
      const imageData = ctx.getImageData(0, y, width, effects.glitch.lineHeight);
      ctx.putImageData(imageData, shift, y);
    }
  };

  const applySaturation = (ctx, width, height) => {
    const { value } = effects.saturation;
    if (value === 100) return;
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      const gray = Math.round(0.299 * r + 0.587 * g + 0.114 * b);
      const sat = value / 100;
      data[i] = Math.round(gray + (r - gray) * sat);
      data[i + 1] = Math.round(gray + (g - gray) * sat);
      data[i + 2] = Math.round(gray + (b - gray) * sat);
    }
    ctx.putImageData(imageData, 0, 0);
  };

  const handleArchive = () => {
    const canvas = canvasRef.current;
    const compressedImageData = compressImage(canvas);
    const timestamp = new Date().toISOString();
    const archives = JSON.parse(localStorage.getItem("archivedImages") || "[]");
    archives.push({ imageData: compressedImageData, timestamp, effects: { ...effects } });
    const trimmedArchives = archives.slice(-10);
    localStorage.setItem("archivedImages", JSON.stringify(trimmedArchives));
    alert("Image archived successfully!");
  };

  const compressImage = (canvas) => {
    const tempCanvas = document.createElement('canvas');
    const tempCtx = tempCanvas.getContext('2d');
    tempCanvas.width = 1080;
    tempCanvas.height = 1080;
    tempCtx.drawImage(canvas, 0, 0, 1080, 1080);
    return tempCanvas.toDataURL('image/png');
  };

  // --- [Logic 1: Color - Adaptive Grid (Quadtree)] ---
  // 색상 차이가 큰 영역은 쪼개고, 비슷한 영역은 합치는 재귀 로직
  const drawAdaptiveGrid = (ctx, imgData, x, y, w, h, depth) => {
    const threshold = 20; // 색상 차이 임계값 (클수록 덜 쪼갬)
    const maxDepth = 6;   // 최대 깊이 (클수록 더 세밀함)

    // 해당 영역의 평균 색상과 오차(Variance) 계산
    let r = 0, g = 0, b = 0;
    let count = 0;

    // 샘플링하여 평균 계산 (성능을 위해 모든 픽셀을 다 보진 않음)
    const step = Math.max(1, Math.floor(w / 10));
    const width = imgData.width;

    // 색상 평균 구하기
    for(let i = x; i < x + w; i += step) {
      for(let j = y; j < y + h; j += step) {
        const idx = (Math.floor(j) * width + Math.floor(i)) * 4;
        if(idx < imgData.data.length) {
            r += imgData.data[idx];
            g += imgData.data[idx+1];
            b += imgData.data[idx+2];
            count++;
        }
      }
    }
    r = Math.floor(r / count);
    g = Math.floor(g / count);
    b = Math.floor(b / count);

    // 오차(Variance) 계산: 평균 색상과 얼마나 다른지
    let variance = 0;
    for(let i = x; i < x + w; i += step) {
      for(let j = y; j < y + h; j += step) {
         const idx = (Math.floor(j) * width + Math.floor(i)) * 4;
         if(idx < imgData.data.length) {
             variance += Math.abs(imgData.data[idx] - r) + 
                         Math.abs(imgData.data[idx+1] - g) + 
                         Math.abs(imgData.data[idx+2] - b);
         }
      }
    }
    variance /= count;

    // 분할 결정 로직
    if (depth < maxDepth && variance > threshold) {
      // 오차가 크면 4등분하여 재귀 호출
      const halfW = w / 2;
      const halfH = h / 2;
      drawAdaptiveGrid(ctx, imgData, x, y, halfW, halfH, depth + 1);
      drawAdaptiveGrid(ctx, imgData, x + halfW, y, halfW, halfH, depth + 1);
      drawAdaptiveGrid(ctx, imgData, x, y + halfH, halfW, halfH, depth + 1);
      drawAdaptiveGrid(ctx, imgData, x + halfW, y + halfH, halfW, halfH, depth + 1);
    } else {
      // 오차가 작거나 최대 깊이면 사각형 그리기
      ctx.fillStyle = `rgb(${r},${g},${b})`;
      // 약간의 틈(gap)을 주어 그리드 느낌 강조
      ctx.fillRect(x, y, w - 0.5, h - 0.5); 
    }
  };


  // --- [Logic 2: Form - Flow Field] ---
  // 이미지의 밝기 변화 방향(Angle)을 따라 선을 그림
  const drawFlowField = (ctx, imgData, width, height) => {
    const step = 15; // 선 간격
    const lineLen = 12; // 선 길이
    const data = imgData.data;

    ctx.lineWidth = 1.2;
    ctx.lineCap = "round";

    for (let y = 0; y < height; y += step) {
      for (let x = 0; x < width; x += step) {
        const i = (y * width + x) * 4;

        // 현재 픽셀 밝기
        const brightness = (data[i] * 0.299 + data[i+1] * 0.587 + data[i+2] * 0.114) / 255;

        // 너무 어두운 곳은 선을 안 그림 (생략)
        if (brightness < 0.1) continue;

        // Sobel Filter로 방향(Angle) 계산 (가로/세로 밝기 변화량)
        // x축 변화량
        let gx = 0;
        let gy = 0;

        // 주변 픽셀 참조 (경계 체크 생략하고 안전한 범위에서)
        if (x > 0 && x < width - 1 && y > 0 && y < height - 1) {
            const left = ((y) * width + (x - 1)) * 4;
            const right = ((y) * width + (x + 1)) * 4;
            const up = ((y - 1) * width + (x)) * 4;
            const down = ((y + 1) * width + (x)) * 4;

            // 간단한 밝기 차이
            const valL = (data[left] + data[left+1] + data[left+2]) / 3;
            const valR = (data[right] + data[right+1] + data[right+2]) / 3;
            const valU = (data[up] + data[up+1] + data[up+2]) / 3;
            const valD = (data[down] + data[down+1] + data[down+2]) / 3;

            gx = valR - valL;
            gy = valD - valU;
        }

        // 각도 계산 (이미지의 엣지 방향과 수직인 흐름을 만듦)
        const angle = Math.atan2(gy, gx) + Math.PI / 2;

        // 선 그리기
        ctx.strokeStyle = `rgba(255, 255, 255, ${0.3 + brightness * 0.5})`; // 밝을수록 선명하게

        ctx.beginPath();
        ctx.moveTo(x, y);
        // 흐름을 따라 선 긋기
        ctx.lineTo(x + Math.cos(angle) * lineLen, y + Math.sin(angle) * lineLen);
        ctx.stroke();

        // 흐름의 끝에 작은 점 찍기 (장식적 요소)
        if (Math.random() > 0.8) {
             ctx.fillStyle = "rgba(255,255,255,0.8)";
             ctx.fillRect(x + Math.cos(angle) * lineLen, y + Math.sin(angle) * lineLen, 2, 2);
        }
      }
    }
  };

  // --- [메인 실행] ---
  const generateImage = (imagePaths) => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;

    const loadImage = (src) =>
      new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.onload = () => resolve(img);
        img.src = src;
      });

    Promise.all(imagePaths.map(loadImage)).then((images) => {
      // 여러 이미지가 있어도 첫 번째 이미지를 메인 로직으로 사용
      // (복잡도를 위해 1장 기준 처리, 합성을 원하면 루프 가능)
      const img = images[0];

      // 1. 이미지 데이터 가져오기 (분석용)
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = width;
      tempCanvas.height = height;
      const tempCtx = tempCanvas.getContext('2d');
      // 화면에 꽉 차게 그림
      const scale = Math.max(width / img.width, height / img.height);
      const x = (width - img.width * scale) / 2;
      const y = (height - img.height * scale) / 2;
      tempCtx.drawImage(img, x, y, img.width * scale, img.height * scale);

      const imgData = tempCtx.getImageData(0, 0, width, height);

      // --- Layer 1: Color Logic (Adaptive Grid) ---
      // 배경을 색상 논리로 채움
      drawAdaptiveGrid(ctx, imgData, 0, 0, width, height, 0);

      // --- Layer 2: Form Logic (Flow Field) ---
      // 형태를 흐름선으로 재해석하여 위에 얹음
      drawFlowField(ctx, imgData, width, height);

      // --- Layer 3: Effects ---
      generateGrain(ctx, width, height);
      applyScanlines(ctx, width, height);
      applySaturation(ctx, width, height);
      applyGlitchEffect(ctx, width, height);
    });
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement("a");
    link.download = "logic_graphic.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  const handleRegenerate = () => {
    setIsFading(true);
    setTimeout(() => {
      generateImage(imagePaths);
      setIsFading(false);
    }, 300);
  };

  const handleBack = () => {
    localStorage.removeItem("generatedImage");
    localStorage.removeItem("selectedImages");
    setImagePaths([]);
    setIsFading(false);
    navigate("/");
  };

  return (
    <div className="ge-container">
      <div className="ge-title-container">
        <img src="/images/logo.gif" alt="Graphic Archive" style={{ height: '60px', width: 'auto', objectFit: 'contain' }} />
      </div>

      <div className="ge-main">
        <div className="ge-box1">
          <div className="ge-effects-panel">
            <h3 style={{ margin: "0 0 15px 0", fontSize: "16px", fontWeight: "500" }}>Logic Controls</h3>
            <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
              {/* UI 컨트롤은 그대로 유지하거나 필요에 따라 수정 */}
              <div>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "5px" }}>
                  <label style={{ fontSize: "14px" }}>Grain</label>
                  <span style={{ fontSize: "12px", opacity: 0.7 }}>{effects.grain.intensity}%</span>
                </div>
                <input type="range" min="0" max="100" step="10" value={effects.grain.intensity} onChange={(e) => setEffects(p => ({...p, grain: {...p.grain, intensity: Number(e.target.value)}}))} style={{ width: "100%" }} />
              </div>
              <div>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "5px" }}>
                  <label style={{ fontSize: "14px" }}>Glitch</label>
                  <span style={{ fontSize: "12px", opacity: 0.7 }}>{effects.glitch.shiftAmount}%</span>
                </div>
                <input type="range" min="0" max="100" step="10" value={effects.glitch.shiftAmount} onChange={(e) => setEffects(p => ({...p, glitch: {...p.glitch, shiftAmount: Number(e.target.value)}}))} style={{ width: "100%" }} />
              </div>
            </div>
          </div>

          <div className="ge-button-container">
            <button onClick={handleBack} className="ge-button ge-button-back">Back</button>
            <button onClick={handleArchive} className="ge-button ge-button-archive">Archive</button>
            <button onClick={handleRegenerate} className="ge-button ge-button-regenerate">Regenerate</button>
            <button onClick={handleDownload} className="ge-button ge-button-download">Download</button>
          </div>
        </div>

        <div className="ge-canvas-container">
          <canvas ref={canvasRef} width={1080} height={1080} className="ge-canvas" style={{ opacity: isFading ? 0.2 : 1 }} />
        </div>
      </div>
    </div>
  );
}

export default Generate;
